const SB_URL='https://oeodnnomgiddkblnlzay.supabase.co';
const SB_KEY='sb_publishable_X06jWDKqV6jgKbaa1PrrbQ_zto1XeTJ';
const sb=supabase.createClient(SB_URL,SB_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gid=()=>crypto.randomUUID();
const today=()=>new Date().toISOString().slice(0,10);
const fmt=d=>d?new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')):'';
const shortDate=d=>d?new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00')):'';
const time=t=>t?String(t).slice(0,5):'—';
const ageAt=(birth,at=today())=>{if(!birth)return null;let b=new Date(birth+'T12:00:00'),d=new Date(at+'T12:00:00'),a=d.getFullYear()-b.getFullYear();if(d<new Date(d.getFullYear(),b.getMonth(),b.getDate()))a--;return a};
const sexLabel=s=>({F:'Mujer',M:'Varón',U:'Sin confirmar'})[s]||'Sin confirmar';
const statusLabel=s=>({unread:'Todavía no leído',preparing:'En preparación',progress:'Avanzando',review:'Necesita revisión',ready:'Confirmado / listo',completed:'Terminado',replacement:'Necesita reemplazo'})[s]||s;
const assignmentLabel=s=>({assigned:'Pendiente de leer',read:'Leído',accepted:'Aceptado',declined:'No puedo hacerlo'})[s]||s;
const iconForLink=u=>{try{let h=new URL(u).hostname;if(h.includes('youtu'))return'▶️';if(h.includes('pinterest'))return'📌';if(h.includes('instagram'))return'📷';if(h.includes('canva'))return'🎨';if(h.includes('drive.google'))return'📄'}catch{}return'🔗'};
const linkType=u=>{try{let h=new URL(u).hostname;if(h.includes('youtu'))return'youtube';if(h.includes('pinterest'))return'pinterest';if(h.includes('instagram'))return'instagram';if(h.includes('canva'))return'canva';if(h.includes('drive.google'))return'drive'}catch{}return'link'};
const youtubeId=u=>{try{let x=new URL(u),h=x.hostname.replace('www.','');if(h==='youtu.be')return x.pathname.slice(1);if(h.includes('youtube.com'))return x.searchParams.get('v')||x.pathname.split('/').filter(Boolean).pop()}catch{}return''};

let session=null, me=null, view=localStorage.getItem('tnt-v8-view')||'my', scheduleTab='timeline', selectedEvent='', selectedDay='', liveMode=false, busy=false;
let S={peopleRaw:[],accounts:[],people:[],moduleAccess:[],events:[],eventMembers:[],tasks:[],assignees:[],links:[],files:[],checks:[],comments:[],availability:[],templates:[],templateItems:[],days:[],items:[],responsibles:[],groups:[],groupMembers:[],notifications:[]};

const person=id=>S.people.find(x=>x.id===id);
const event=id=>S.events.find(x=>x.id===id);
const task=id=>S.tasks.find(x=>x.id===id);
const myId=()=>me?.id;
const isAdmin=()=>me?.system_role==='admin';
const isPastor=()=>me?.ministry_role==='Pastor/a';
const canManage=eventId=>isAdmin()||isPastor()||S.eventMembers.some(x=>x.event_id===eventId&&x.person_id===myId()&&x.event_role==='organizer');
const eventOrganizers=id=>S.eventMembers.filter(x=>x.event_id===id&&x.event_role==='organizer').map(x=>person(x.person_id)).filter(Boolean);
const taskAssignees=id=>S.assignees.filter(x=>x.task_id===id).map(x=>({...x,person:person(x.person_id)}));
const dayItems=id=>S.items.filter(x=>x.day_id===id).sort((a,b)=>(a.starts_at||'99:99').localeCompare(b.starts_at||'99:99')||a.sort_order-b.sort_order);
const itemResponsibles=id=>S.responsibles.filter(x=>x.item_id===id).map(x=>person(x.person_id)).filter(Boolean);
const navDefs=[['my','⌂','Mi TNT'],['schedule','🗓','Cronograma'],['saturdays','◷','Sábados'],['events','◇','Eventos'],['tasks','✓','Mis tareas'],['team','◉','Equipo'],['templates','▦','Plantillas']];

function toast(msg){let n=document.createElement('div');n.textContent=msg;n.style='position:fixed;left:50%;bottom:92px;transform:translateX(-50%);z-index:120;background:#fff;color:#111;padding:11px 15px;border-radius:13px;font-weight:900;box-shadow:0 15px 50px #0008';document.body.appendChild(n);setTimeout(()=>n.remove(),2400)}
function showError(err){console.error(err);modal(`<div class="sheethead"><h2>Algo salió mal</h2><button class="close" data-close>×</button></div><div class="dangerbox">${esc(err?.message||String(err))}</div>`)}
function modal(html,wide=false){$('#modal').innerHTML=`<div class="modal"><section class="sheet ${wide?'wide':''}">${html}</section></div>`;$$('[data-close]').forEach(b=>b.onclick=closeModal);$('.modal')?.addEventListener('click',e=>{if(e.target.classList.contains('modal'))closeModal()})}
function closeModal(){$('#modal').innerHTML=''}

async function init(){
  const {data}=await sb.auth.getSession(); session=data.session;
  sb.auth.onAuthStateChange(async(_e,s)=>{session=s;if(s)await loadAll();else renderAuth()});
  if(session)await loadAll();else renderAuth();
}

function renderAuth(){
  $('#app').innerHTML=`<div class="auth"><div class="authbox"><div class="authmark">T</div><div class="eyebrow">TNT · Trastornadores</div><h1>Tu equipo, en un solo lugar.</h1><p class="subtitle">Ingresá para ver tus tareas, cronogramas, eventos, notificaciones y responsabilidades.</p><button class="oauth" id="googleLogin">G&nbsp;&nbsp;Continuar con Google</button><div class="divider">o por email</div><form class="form" id="magicForm"><div class="field"><label>Email</label><input id="magicEmail" type="email" required placeholder="vos@email.com"></div><button class="btn primary">Enviarme un enlace de acceso</button></form><p class="subtitle" style="margin-top:16px">La primera cuenta TNT que ingrese queda como Admin inicial. Después podés otorgar Admin a otras personas desde Administración.</p></div></div>`;
  $('#googleLogin').onclick=async()=>{const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/organizacion/'}});if(error)showError(error)};
  $('#magicForm').onsubmit=async e=>{e.preventDefault();let email=$('#magicEmail').value.trim();const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/organizacion/'}});if(error)showError(error);else toast('Revisá tu email para ingresar')};
}

async function loadAll(){
  if(busy)return; busy=true; $('#app').innerHTML='<div class="loader"><div><div class="spinner"></div>Cargando Organización…</div></div>';
  try{
    const tables=[
      ['peopleRaw','tnt_people','*'],['accounts','tnt_accounts','*'],['moduleAccess','tnt_module_access','*'],['events','tnt_events','*'],['eventMembers','tnt_event_members','*'],['tasks','tnt_tasks','*'],['assignees','tnt_task_assignees','*'],['links','tnt_task_links','*'],['files','tnt_task_files','*'],['checks','tnt_task_checklist','*'],['comments','tnt_task_comments','*'],['availability','tnt_availability','*'],['templates','tnt_templates','*'],['templateItems','tnt_template_items','*'],['days','tnt_schedule_days','*'],['items','tnt_schedule_items','*'],['responsibles','tnt_schedule_responsibles','*'],['groups','tnt_groups','*'],['groupMembers','tnt_group_members','*'],['notifications','tnt_notifications','*']
    ];
    const results=await Promise.all(tables.map(async([k,t,sel])=>{let q=sb.from(t).select(sel);if(t==='tnt_notifications')q=q.order('created_at',{ascending:false}).limit(200);if(t==='tnt_events')q=q.order('start_date',{ascending:true});const {data,error}=await q;if(error)throw error;return[k,data||[]]}));
    results.forEach(([k,d])=>S[k]=d);
    const accountByPerson=new Map(S.accounts.map(a=>[a.person_id,a]));
    S.people=S.peopleRaw.map(p=>{const a=accountByPerson.get(p.id)||{};return {...p,birth_date:p.birthday||null,sex_confirmed:p.sex&&p.sex!=='U',email:a.email||'',nickname:a.nickname||'',avatar_url:a.avatar_url||'',ministry_role:a.ministry_role||'Timoteo',system_role:a.system_role||'user',service_areas:a.service_areas||[],skills:a.skills||[],availability_days:a.availability_days||[],service_preferences:a.service_preferences||{},bio:a.bio||'',auth_user_id:a.auth_user_id||null,account_exists:!!a.person_id,active:p.active!==false&&a.enabled!==false};});
    me=S.people.find(p=>p.auth_user_id===session.user.id)||null;
    if(!me){await new Promise(r=>setTimeout(r,500));const {data}=await sb.from('tnt_people').select('*').eq('auth_user_id',session.user.id).maybeSingle();me=data;if(me)S.people.push(me)}
    if(!selectedEvent){let upcoming=S.events.find(e=>e.end_date>=today());selectedEvent=upcoming?.id||S.events[0]?.id||''}
    if(selectedEvent&&!selectedDay)selectedDay=S.days.find(d=>d.event_id===selectedEvent)?.id||'';
    setupRealtime(); render(); generateLocalReminders();
  }catch(err){renderBackendError(err)}finally{busy=false}
}

function renderBackendError(err){$('#app').innerHTML=`<div class="auth"><div class="authbox"><div class="authmark">!</div><h1>Estamos preparando TNT</h1><p class="subtitle">La base central todavía no está lista o está terminando de iniciar.</p><div class="dangerbox">${esc(err?.message||String(err))}</div><button class="btn primary" style="width:100%;margin-top:15px" onclick="loadAll()">Reintentar</button></div></div>`}

let realtimeStarted=false;
function setupRealtime(){if(realtimeStarted||!session)return;realtimeStarted=true;sb.channel('tnt-live').on('postgres_changes',{event:'INSERT',schema:'public',table:'tnt_notifications'},payload=>{let n=payload.new;if(n.person_id===myId()||!n.person_id){S.notifications.unshift(n);renderHeaderOnly();if(Notification.permission==='granted')new Notification(n.title,{body:n.body||'',tag:n.id})}}).subscribe()}

function shell(content){
  const unread=S.notifications.filter(n=>(n.person_id===myId()||!n.person_id)&&!n.read_at).length;
  const avatar=me?.avatar_url?`<img src="${esc(me.avatar_url)}" alt="">`:esc((me?.nickname||me?.full_name||'?').slice(0,2).toUpperCase());
  return `<div class="app"><header class="top"><div class="logo">T</div><div class="brand"><b>Organización</b><small>TNT</small></div><div class="grow"></div>${isAdmin()?'<button class="topbtn" data-open-admin>⚙ <span class="txt">Admin</span></button>':''}<button class="topbtn" data-notes>🔔${unread?'<i class="badgeDot"></i>':''}</button><button class="avatarbtn" data-profile>${avatar}</button></header>${content}<nav class="bottom">${navDefs.map(([id,ic,lab])=>`<button class="nav ${view===id?'on':''}" data-view="${id}"><b>${ic}</b><span>${lab}</span></button>`).join('')}</nav></div>`;
}
function renderHeaderOnly(){let old=view;render();view=old}
function render(){localStorage.setItem('tnt-v8-view',view);let c=view==='my'?renderMy():view==='schedule'?renderSchedule():view==='saturdays'?renderSaturdays():view==='events'?renderEvents():view==='tasks'?renderTasks():view==='team'?renderTeam():renderTemplates();$('#app').innerHTML=shell(c);bindGlobal()}
function bindGlobal(){
  $$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
  $('[data-profile]')?.addEventListener('click',profileModal);
  $('[data-notes]')?.addEventListener('click',notificationsModal);
  $('[data-open-admin]')?.addEventListener('click',adminModal);
}

function renderMy(){
  const mine=S.assignees.filter(a=>a.person_id===myId()).map(a=>({a,t:task(a.task_id)})).filter(x=>x.t).sort((a,b)=>(a.t.due_at||'9999').localeCompare(b.t.due_at||'9999'));
  const upcoming=S.events.filter(e=>e.end_date>=today()).slice(0,4);
  const un=S.notifications.filter(n=>(n.person_id===myId()||!n.person_id)&&!n.read_at).slice(0,4);
  const bdays=S.people.filter(p=>p.birth_date&&p.birth_date.slice(5)===today().slice(5));
  return `<main class="page"><div class="eyebrow">Mi TNT</div><div class="titleRow"><div><h1>Hola, ${esc(me?.nickname||me?.full_name||'')} 👋</h1><p class="subtitle">Todo lo que te toca, lo que viene y lo que necesita tu atención.</p></div><div class="toolbar"><button class="btn" data-availability>Disponibilidad</button></div></div><div class="grid g4"><div class="stat"><b>${mine.filter(x=>x.a.assignment_status!=='declined').length}</b><span>asignaciones</span></div><div class="stat"><b>${mine.filter(x=>x.t.status==='replacement').length}</b><span>necesitan reemplazo</span></div><div class="stat"><b>${upcoming.length}</b><span>próximos eventos</span></div><div class="stat"><b>${un.length}</b><span>notificaciones nuevas</span></div></div>${bdays.length?`<div class="section"><h2>🎂 Cumpleaños de hoy</h2></div><div class="card">${bdays.map(p=>`<b>${esc(p.nickname||p.full_name)}</b>`).join(' · ')}</div>`:''}<div class="section"><h2>Próximo</h2></div>${mine.length?`<div class="grid g2">${mine.slice(0,4).map(x=>taskCard(x.t,x.a)).join('')}</div>`:`<div class="empty">No tenés asignaciones pendientes.</div>`}<div class="section"><h2>Próximos eventos</h2></div><div class="grid g2">${upcoming.map(eventCard).join('')||'<div class="empty">No hay eventos próximos.</div>'}</div><div class="section"><h2>Notificaciones</h2><button class="btn small" data-notes>Ver todas</button></div>${un.length?`<div class="list">${un.map(notificationCard).join('')}</div>`:`<div class="empty">Estás al día.</div>`}</main>`;
}
function taskCard(t,a){let ev=event(t.event_id);return `<button class="card click" data-task-open="${t.id}"><div class="chips"><span class="status ${t.status}">${statusLabel(t.status)}</span>${a?`<span class="chip">${assignmentLabel(a.assignment_status)}</span>`:''}</div><h3 style="margin-top:10px">${esc(t.icon||'✓')} ${esc(t.title)}</h3><p>${esc(ev?.name||'')} ${t.due_at?'· vence '+shortDate(t.due_at.slice(0,10)):''}</p></button>`}
function eventCard(e){let org=eventOrganizers(e.id).map(p=>p.nickname||p.full_name).join(', ');return `<button class="card click" data-event-open="${e.id}"><div class="chips"><span class="chip">${e.kind==='saturday'?'Sábado':e.kind==='camp'?'Campamento':'Evento'}</span><span class="chip">${esc(e.status)}</span></div><h3 style="margin-top:10px">${esc(e.name)}</h3><p>${fmt(e.start_date)}${e.end_date!==e.start_date?' → '+fmt(e.end_date):''}${org?' · '+esc(org):''}</p></button>`}
function notificationCard(n){return `<button class="rowCard" data-note="${n.id}"><div class="ico">🔔</div><div><h4>${esc(n.title)}</h4><p>${esc(n.body||'')}</p></div><span class="arr">›</span></button>`}

function renderSchedule(){
  let ev=event(selectedEvent); const evs=S.events.filter(e=>e.end_date>=today()||e.kind==='camp');
  if(!ev&&evs.length){selectedEvent=evs[0].id;ev=evs[0]}
  let days=ev?S.days.filter(d=>d.event_id===ev.id).sort((a,b)=>a.sort_order-b.sort_order):[];
  if(ev&&!selectedDay&&days[0])selectedDay=days[0].id;
  if(selectedDay&&!days.some(d=>d.id===selectedDay))selectedDay=days[0]?.id||'';
  return `<main class="page ${liveMode?'live':''}"><div class="eyebrow">Organización del evento</div><div class="titleRow"><div><h1>${liveMode?'▶ Modo evento':'Cronograma'}</h1><p class="subtitle">Días, horarios, juegos, responsables, videos, materiales y grupos.</p></div><div class="toolbar"><select class="btn" id="eventSelect">${evs.map(e=>`<option value="${e.id}" ${e.id===selectedEvent?'selected':''}>${esc(e.name)}</option>`).join('')}</select>${ev&&canManage(ev.id)?'<button class="btn" data-edit-event>Editar evento</button>':''}<button class="btn ${liveMode?'green':''}" data-live>${liveMode?'Salir del modo evento':'▶ Modo evento'}</button></div></div>${!ev?`<div class="empty">Todavía no hay eventos. Creá uno desde Eventos.</div>`:`<div class="tabs"><button class="tab ${scheduleTab==='timeline'?'on':''}" data-stab="timeline">Cronograma</button><button class="tab ${scheduleTab==='groups'?'on':''}" data-stab="groups">Grupos por día</button></div>${scheduleTab==='timeline'?renderTimeline(ev,days):renderGroups(ev,days)}${renderEventTasks(ev)}`}</main>`;
}

function renderEventTasks(ev){
  const ts=S.tasks.filter(t=>t.event_id===ev.id&&!t.parent_task_id).sort((a,b)=>a.sort_order-b.sort_order||a.created_at.localeCompare(b.created_at));
  return `<div class="section"><h2>Tareas y equipos</h2>${canManage(ev.id)?'<button class="btn small primary" data-add-task>+ Tarea</button>':''}</div><div class="grid g2">${ts.map(t=>taskCard(t,S.assignees.find(a=>a.task_id===t.id&&a.person_id===myId()))).join('')||'<div class="empty">Sin tareas. Podés agregar Merch, Decoración, Multimedia, Recepción, Buffet o cualquier equipo.</div>'}</div>`;
}

function renderTimeline(ev,days){
  if(liveMode){let all=days.flatMap(d=>dayItems(d.id).map(i=>({d,i}))).sort((a,b)=>(a.d.date||'').localeCompare(b.d.date||'')||(a.i.starts_at||'').localeCompare(b.i.starts_at||''));return `<div class="section"><h2>${esc(ev.name)}</h2><small>${fmt(ev.start_date)} → ${fmt(ev.end_date)}</small></div><div class="timeline">${all.map(({d,i})=>timelineItem(i,d,true)).join('')||'<div class="empty">Sin cronograma cargado.</div>'}</div>`}
  return `<div class="section"><h2>Días</h2>${canManage(ev.id)?'<button class="btn small primary" data-add-day>+ Día</button>':''}</div><div class="tabs">${days.map(d=>`<button class="tab ${d.id===selectedDay?'on':''}" data-day="${d.id}">${esc(d.label)}${d.date?' · '+shortDate(d.date):''}</button>`).join('')}</div>${selectedDay?`<div class="section"><h2>${esc(S.days.find(d=>d.id===selectedDay)?.label||'')}</h2>${canManage(ev.id)?'<button class="btn small primary" data-add-item>+ Actividad / juego</button>':''}</div><div class="timeline">${dayItems(selectedDay).map(i=>timelineItem(i,S.days.find(d=>d.id===selectedDay),false)).join('')||'<div class="empty">Este día todavía no tiene actividades.</div>'}</div>`:`<div class="empty">Agregá el primer día del cronograma.</div>`}`
}
function timelineItem(i,d,live){let rs=itemResponsibles(i.id);let linked=i.task_id?task(i.task_id):null;return `<div class="timeItem"><div class="time">${time(i.starts_at)}</div><div class="timebox" data-item="${i.id}"><div style="display:flex;justify-content:space-between;gap:10px"><div><div class="chips" style="margin-top:0"><span class="chip">${i.item_type==='game'?'🎮 Juego':i.item_type==='meal'?'🍽 Comida':i.item_type==='meeting'?'🎤 Reunión':'Actividad'}</span>${linked?`<span class="status ${linked.status}">${statusLabel(linked.status)}</span>`:''}</div><h3 style="margin-top:8px">${esc(i.title)}</h3><p>${i.duration_minutes?i.duration_minutes+' min · ':''}${esc(i.location||'')}${i.description?' · '+esc(i.description.slice(0,100)):''}</p>${rs.length?`<p>Responsable${rs.length>1?'s':''}: ${rs.map(p=>`<button class="respLink" data-resp="${p.id}">${esc(p.nickname||p.full_name)}</button>`).join(' · ')}</p>`:''}</div>${i.video_url?'<div class="ico">▶️</div>':'<span class="arr">›</span>'}</div></div></div>`}

function renderGroups(ev,days){
  let day=days.find(d=>d.id===selectedDay)||days[0]; if(day)selectedDay=day.id;
  const gs=day?S.groups.filter(g=>g.day_id===day.id).sort((a,b)=>a.sort_order-b.sort_order):[];
  const participants=S.eventMembers.filter(x=>x.event_id===ev.id&&x.event_role==='participant').map(x=>person(x.person_id)).filter(Boolean);
  const missing=participants.filter(p=>!p.birth_date||!p.sex_confirmed||!p.sex);
  return `<div class="section"><h2>Día para los juegos</h2>${canManage(ev.id)?'<div class="toolbar"><button class="btn small" data-import-camp>Importar participantes de Campamento</button><button class="btn small" data-config-groups>Configurar equipos</button><button class="btn small primary" data-generate-groups>Mezclar equilibrado</button></div>':''}</div><div class="tabs">${days.map(d=>`<button class="tab ${d.id===selectedDay?'on':''}" data-day="${d.id}">${esc(d.label)}</button>`).join('')}</div>${missing.length?`<div class="warn" style="margin-top:12px">⚠️ ${missing.length} participante${missing.length>1?'s':''} tienen sexo o fecha de nacimiento sin confirmar. No voy a inferir sexo por el nombre. Completalos antes de generar una división equilibrada. <button class="btn small" data-fix-missing style="margin-left:8px">Completar</button></div>`:''}<div class="section"><h2>Participantes</h2><small>${participants.length} en este evento</small></div>${gs.length?`<div class="groupGrid">${gs.map(g=>groupCard(g,day)).join('')}</div>`:`<div class="empty">Todavía no hay equipos para este día. Por defecto podés usar Rojo y Azul, pero son configurables.</div>`}`;
}
function groupCard(g,day){let ms=S.groupMembers.filter(x=>x.group_id===g.id).map(x=>({gm:x,p:person(x.person_id)})).filter(x=>x.p);let avg=ms.length?Math.round(ms.reduce((a,x)=>a+(x.gm.age_snapshot||ageAt(x.p.birth_date,day.date)||0),0)/ms.length):0;return `<div class="group"><div class="groupHead" style="border-top:4px solid ${esc(g.color)}"><span>${esc(g.name)}</span><small>${ms.length} · prom. ${avg||'—'} años</small></div><div class="groupBody">${ms.map(x=>`<button class="member" data-move-person="${x.p.id}" data-from-group="${g.id}"><span>${esc(x.p.nickname||x.p.full_name)}</span><small>${sexLabel(x.p.sex)} · ${x.gm.age_snapshot??ageAt(x.p.birth_date,day.date)??'—'}</small></button>`).join('')||'<div class="muted">Sin integrantes</div>'}</div></div>`}

function renderSaturdays(){let xs=S.events.filter(e=>e.kind==='saturday').sort((a,b)=>a.start_date.localeCompare(b.start_date));return `<main class="page"><div class="eyebrow">Reuniones normales</div><div class="titleRow"><div><h1>Sábados</h1><p class="subtitle">Plantilla base: Bienvenida, Dinámica, Ofrenda, Ministración y Palabra / Prédica. Todo editable.</p></div>${isAdmin()||isPastor()?'<button class="btn primary" data-new-event="saturday">+ Preparar sábado</button>':''}</div><div class="grid g2">${xs.map(eventCard).join('')||'<div class="empty">Todavía no hay sábados preparados.</div>'}</div></main>`}
function renderEvents(){let xs=S.events.filter(e=>e.kind!=='saturday').sort((a,b)=>a.start_date.localeCompare(b.start_date));return `<main class="page"><div class="eyebrow">Congresos · campamentos · salidas · vigilias</div><div class="titleRow"><div><h1>Eventos</h1><p class="subtitle">Equipos, tareas, responsables, presupuesto, materiales y seguimiento.</p></div>${isAdmin()||isPastor()?'<button class="btn primary" data-new-event="event">+ Evento</button>':''}</div><div class="grid g2">${xs.map(eventCard).join('')||'<div class="empty">Todavía no hay eventos.</div>'}</div></main>`}

function renderTasks(){
  let mine=S.assignees.filter(a=>a.person_id===myId()).map(a=>({a,t:task(a.task_id)})).filter(x=>x.t);
  return `<main class="page"><div class="eyebrow">Responsabilidades</div><div class="titleRow"><div><h1>Mis tareas</h1><p class="subtitle">Lectura, aceptación y avance son cosas separadas: confirmar que viste algo no lo marca como terminado.</p></div></div><div class="grid g2">${mine.map(x=>taskCard(x.t,x.a)).join('')||'<div class="empty">Todavía no tenés tareas asignadas.</div>'}</div></main>`
}

function renderTeam(){
  let monthKey=today().slice(0,7);let counts=new Map();S.assignees.forEach(a=>{let t=task(a.task_id);if(t?.due_at?.startsWith(monthKey)||event(t?.event_id)?.start_date?.startsWith(monthKey))counts.set(a.person_id,(counts.get(a.person_id)||0)+1)});
  return `<main class="page"><div class="eyebrow">Personas TNT</div><div class="titleRow"><div><h1>Equipo</h1><p class="subtitle">Una sola ficha para roles, habilidades, preferencias, disponibilidad y carga de trabajo.</p></div>${isAdmin()?'<button class="btn primary" data-new-person>+ Persona</button>':''}</div><div class="grid g3">${S.people.filter(p=>p.active).map(p=>`<button class="card click" data-person-open="${p.id}"><div style="display:flex;gap:12px;align-items:center"><div class="avatar">${p.avatar_url?`<img src="${esc(p.avatar_url)}">`:esc((p.nickname||p.full_name||'?').slice(0,2).toUpperCase())}</div><div><h3>${esc(p.full_name)}</h3><p>${esc(p.nickname||'')} · ${esc(p.ministry_role)}</p></div></div><div class="chips"><span class="chip ${p.system_role==='admin'?'adminTag':''}">${p.system_role==='admin'?'Admin':'Usuario'}</span><span class="chip">${counts.get(p.id)||0} asignaciones este mes</span>${p.birth_date?`<span class="chip">${ageAt(p.birth_date)} años</span>`:''}</div></button>`).join('')}</div></main>`
}

function renderTemplates(){return `<main class="page"><div class="eyebrow">Reutilizar lo que funciona</div><div class="titleRow"><div><h1>Plantillas</h1><p class="subtitle">Sábado normal, evangelismo, congreso y cualquier estructura que quieras guardar.</p></div>${isAdmin()||isPastor()?'<button class="btn primary" data-new-template>+ Plantilla</button>':''}</div><div class="grid g2">${S.templates.map(t=>{let items=S.templateItems.filter(i=>i.template_id===t.id).sort((a,b)=>a.sort_order-b.sort_order);return `<button class="card click" data-template="${t.id}"><div class="chips"><span class="chip">${t.kind}</span>${t.is_default?'<span class="chip">Predeterminada</span>':''}</div><h3 style="margin-top:10px">${esc(t.name)}</h3><p>${esc(t.description||'')}</p><div class="chips">${items.slice(0,6).map(i=>`<span class="chip">${esc(i.icon||'✓')} ${esc(i.title)}</span>`).join('')}</div></button>`}).join('')}</div></main>`}

function bindViewActions(){
  $('#eventSelect')?.addEventListener('change',e=>{selectedEvent=e.target.value;selectedDay=S.days.find(d=>d.event_id===selectedEvent)?.id||'';render()});
  $$('[data-stab]').forEach(b=>b.onclick=()=>{scheduleTab=b.dataset.stab;render()});
  $$('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.day;render()});
  $$('[data-task-open]').forEach(b=>b.onclick=()=>taskModalView(b.dataset.taskOpen));
  $$('[data-event-open]').forEach(b=>b.onclick=()=>{selectedEvent=b.dataset.eventOpen;selectedDay=S.days.find(d=>d.event_id===selectedEvent)?.id||'';view='schedule';render()});
  $$('[data-note]').forEach(b=>b.onclick=()=>openNotification(b.dataset.note));
  $$('[data-new-event]').forEach(b=>b.onclick=()=>eventEditor(null,b.dataset.newEvent));
  $('[data-edit-event]')?.addEventListener('click',()=>eventEditor(event(selectedEvent)));
  $('[data-live]')?.addEventListener('click',()=>{liveMode=!liveMode;render()});
  $('[data-add-day]')?.addEventListener('click',dayEditor);
  $('[data-add-item]')?.addEventListener('click',()=>itemEditor());
  $('[data-add-task]')?.addEventListener('click',()=>taskEditor(null,selectedEvent,null));
  $$('[data-item]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-resp]'))return;itemDetail(b.dataset.item)});
  $$('[data-resp]').forEach(b=>b.onclick=e=>{e.stopPropagation();responsibilitiesModal(b.dataset.resp)});
  $('[data-import-camp]')?.addEventListener('click',importCampParticipants);
  $('[data-config-groups]')?.addEventListener('click',groupsConfigModal);
  $('[data-generate-groups]')?.addEventListener('click',generateGroups);
  $('[data-fix-missing]')?.addEventListener('click',missingPeopleModal);
  $$('[data-move-person]').forEach(b=>b.onclick=()=>movePersonModal(b.dataset.movePerson,b.dataset.fromGroup));
  $$('[data-person-open]').forEach(b=>b.onclick=()=>personDetail(b.dataset.personOpen));
  $('[data-new-person]')?.addEventListener('click',()=>personEditor());
  $('[data-new-template]')?.addEventListener('click',()=>templateEditor());
  $$('[data-template]').forEach(b=>b.onclick=()=>templateEditor(S.templates.find(t=>t.id===b.dataset.template)));
  $('[data-availability]')?.addEventListener('click',availabilityModal);
  $$('[data-notes]').forEach(b=>b.onclick=notificationsModal);
}
const originalRender=render;
render=function(){originalRender();bindViewActions()};

function profileModal(){personEditor(me,true)}
async function personEditor(p=null,self=false){
  p=p||{id:null,full_name:'',nickname:'',email:'',phone:'',ministry_role:'Timoteo',system_role:'user',service_areas:[],skills:[],availability_days:[],service_preferences:{},bio:'',sex:'',sex_confirmed:false,birth_date:''};
  const common=['Bienvenida','Dinámica','Ofrenda','Ministración','Prédica','Multimedia','Fotografía','Video','Diseño','Recepción','Intercesión','Sonido','Buffet','Organización'];
  modal(`<div class="sheethead"><h2>${p.id?'Perfil':'Nueva persona'}</h2><button class="close" data-close>×</button></div><form class="form" id="personForm"><div class="formRow"><div class="field"><label>Nombre completo</label><input name="name" value="${esc(p.full_name||'')}" required></div><div class="field"><label>Sobrenombre</label><input name="nick" value="${esc(p.nickname||'')}"></div></div><div class="formRow"><div class="field"><label>Email</label><input type="email" name="email" value="${esc(p.email||'')}"></div><div class="field"><label>WhatsApp</label><input name="phone" value="${esc(p.phone||'')}"></div></div><div class="formRow"><div class="field"><label>Fecha de nacimiento</label><input type="date" name="birth" value="${esc(p.birth_date||'')}"></div><div class="field"><label>Sexo confirmado</label><select name="sex"><option value="">Sin confirmar</option><option value="F" ${p.sex==='F'?'selected':''}>Mujer</option><option value="M" ${p.sex==='M'?'selected':''}>Varón</option><option value="U" ${p.sex==='U'?'selected':''}>Sin confirmar</option></select></div></div>${isAdmin()?`<div class="formRow"><div class="field"><label>Rol TNT</label><select name="ministry">${['Pastor/a','Colaborador','Líder','Timoteo'].map(r=>`<option ${p.ministry_role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Cuenta</label><select name="active"><option value="true" ${p.active!==false?'selected':''}>Activa</option><option value="false" ${p.active===false?'selected':''}>Desactivada</option></select></div></div>`:''}<div class="field"><label>Foto de perfil</label><input type="file" name="avatar" accept="image/*"><small class="muted">Si ingresás con Google también podemos usar la foto de Google.</small></div><div class="field"><label>Áreas en las que sirve / le gusta servir</label><div class="checkGrid">${common.map(x=>`<label class="check"><input type="checkbox" name="area" value="${esc(x)}" ${(p.service_areas||[]).includes(x)?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div></div><div class="field"><label>Talentos / habilidades</label><input name="skills" value="${esc((p.skills||[]).join(', '))}" placeholder="Fotografía, video, diseño…"></div><div class="field"><label>Preferencias para servir</label><div class="grid g3">${common.slice(0,9).map(x=>`<div class="field"><label>${esc(x)}</label><select name="pref:${esc(x)}"><option value="neutral" ${(p.service_preferences||{})[x]==='neutral'?'selected':''}>Me da igual</option><option value="love" ${(p.service_preferences||{})[x]==='love'?'selected':''}>Me encanta</option><option value="avoid" ${(p.service_preferences||{})[x]==='avoid'?'selected':''}>Prefiero no hacerlo</option></select></div>`).join('')}</div></div><div class="field"><label>Sobre mí</label><textarea name="bio">${esc(p.bio||'')}</textarea></div><button class="btn primary">Guardar perfil</button></form>` ,true);
  $('#personForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),prefs={};for(const [k,v] of f.entries())if(k.startsWith('pref:'))prefs[k.slice(5)]=v;let personPayload={full_name:String(f.get('name')).trim(),normalized_name:String(f.get('name')).trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,''),phone:String(f.get('phone')).trim()||null,birthday:String(f.get('birth'))||null,sex:String(f.get('sex')||'U'),source:p.source||'tnt',active:isAdmin()?String(f.get('active'))==='true':p.active!==false};let accountPayload={email:String(f.get('email')).trim()||null,nickname:String(f.get('nick')).trim()||null,service_areas:f.getAll('area').map(String),skills:String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean),service_preferences:prefs,bio:String(f.get('bio')||'').trim()||null};if(isAdmin())accountPayload.ministry_role=String(f.get('ministry'));try{let avatar=f.get('avatar');if(avatar&&avatar.size){let path=`${p.id||session.user.id}/${Date.now()}-${avatar.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;let up=await sb.storage.from('tnt-avatars').upload(path,avatar,{upsert:false});if(up.error)throw up.error;accountPayload.avatar_url=sb.storage.from('tnt-avatars').getPublicUrl(path).data.publicUrl}let pid=p.id;if(pid){let pr=await sb.from('tnt_people').update(personPayload).eq('id',pid).select().single();if(pr.error)throw pr.error;let existingAccount=S.accounts.find(a=>a.person_id===pid);if(existingAccount){let ar=await sb.from('tnt_accounts').update(accountPayload).eq('person_id',pid);if(ar.error)throw ar.error}else if(isAdmin()){let ar=await sb.from('tnt_accounts').insert({person_id:pid,...accountPayload,system_role:'user',enabled:true});if(ar.error)throw ar.error}}else{if(!isAdmin())throw new Error('Solo Admin puede crear personas.');let pr=await sb.from('tnt_people').insert(personPayload).select().single();if(pr.error)throw pr.error;pid=pr.data.id;let ar=await sb.from('tnt_accounts').insert({person_id:pid,...accountPayload,system_role:'user',enabled:true});if(ar.error)throw ar.error}closeModal();toast('Perfil guardado');await loadAll()}catch(err){showError(err)}}
}

function personDetail(id){let p=person(id);if(!p)return;let assigns=S.assignees.filter(a=>a.person_id===id),month=today().slice(0,7),monthCount=assigns.filter(a=>{let t=task(a.task_id),e=event(t?.event_id);return t?.due_at?.startsWith(month)||e?.start_date?.startsWith(month)}).length;let prefs=Object.entries(p.service_preferences||{}).filter(([,v])=>v==='love').map(([k])=>k);modal(`<div class="sheethead"><h2>${esc(p.nickname||p.full_name)}</h2><button class="close" data-close>×</button></div><div class="grid g3"><div class="stat"><b>${monthCount}</b><span>asignaciones este mes</span></div><div class="stat"><b>${p.birth_date?ageAt(p.birth_date):'—'}</b><span>edad</span></div><div class="stat"><b>${esc(p.ministry_role)}</b><span>rol TNT</span></div></div><div class="section"><h2>Perfil</h2>${isAdmin()||p.id===myId()?`<button class="btn small" id="editPerson">Editar</button>`:''}</div><div class="card"><p>${esc(p.bio||'Sin descripción')}</p><div class="chips">${(p.service_areas||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>${prefs.length?`<p><b>Le encanta:</b> ${esc(prefs.join(', '))}</p>`:''}</div><div class="section"><h2>Responsabilidades</h2></div><div class="list">${assigns.slice(0,12).map(a=>{let t=task(a.task_id),e=event(t?.event_id);return t?`<button class="rowCard" data-p-task="${t.id}"><div class="ico">${esc(t.icon||'✓')}</div><div><h4>${esc(t.title)}</h4><p>${esc(e?.name||'')} · ${assignmentLabel(a.assignment_status)}</p></div><span class="status ${t.status}">${statusLabel(t.status)}</span></button>`:''}).join('')||'<div class="empty">Sin asignaciones.</div>'}</div>` ,true);$('#editPerson')?.addEventListener('click',()=>personEditor(p,p.id===myId()));$$('[data-p-task]').forEach(b=>b.onclick=()=>taskModalView(b.dataset.pTask))}

function availabilityModal(){let rows=S.availability.filter(a=>a.person_id===myId()).sort((a,b)=>a.date.localeCompare(b.date));modal(`<div class="sheethead"><h2>Mi disponibilidad</h2><button class="close" data-close>×</button></div><form class="form" id="availForm"><div class="formRow"><div class="field"><label>Fecha</label><input type="date" name="date" required></div><div class="field"><label>Estado</label><select name="status"><option value="available">🟢 Disponible</option><option value="maybe">🟡 Probablemente no pueda</option><option value="unavailable">🔴 No puedo</option></select></div></div><div class="field"><label>Nota</label><input name="note" placeholder="Viaje, estudio, trabajo…"></div><button class="btn primary">Guardar disponibilidad</button></form><div class="section"><h2>Fechas marcadas</h2></div><div class="list">${rows.map(a=>`<div class="rowCard"><div>${a.status==='available'?'🟢':a.status==='maybe'?'🟡':'🔴'}</div><div><h4>${fmt(a.date)}</h4><p>${esc(a.note||'')}</p></div></div>`).join('')||'<div class="empty">No marcaste fechas todavía.</div>'}</div>`);$('#availForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),payload={person_id:myId(),date:f.get('date'),status:f.get('status'),note:String(f.get('note')||'')||null};let {error}=await sb.from('tnt_availability').upsert(payload);if(error)return showError(error);closeModal();await loadAll()}}

async function notificationsModal(){let ns=S.notifications.filter(n=>n.person_id===myId()||!n.person_id);modal(`<div class="sheethead"><h2>Notificaciones</h2><button class="close" data-close>×</button></div><div class="toolbar" style="margin:8px 0 14px"><button class="btn small" id="allowNotifications">Activar avisos del navegador</button>${isAdmin()||isPastor()?'<button class="btn small primary" id="sendAnnouncement">Enviar aviso</button>':''}</div><div class="list">${ns.map(notificationCard).join('')||'<div class="empty">Sin notificaciones.</div>'}</div>`);$('#allowNotifications').onclick=async()=>{let r=await Notification.requestPermission();toast(r==='granted'?'Avisos activados':'No se habilitaron avisos')};$('#sendAnnouncement')?.addEventListener('click',announcementModal);$$('[data-note]').forEach(b=>b.onclick=()=>openNotification(b.dataset.note))}
async function openNotification(id){let n=S.notifications.find(x=>x.id===id);if(!n)return;if(!n.read_at){await sb.from('tnt_notifications').update({read_at:new Date().toISOString()}).eq('id',id);n.read_at=new Date().toISOString()}if(n.task_id){closeModal();taskModalView(n.task_id)}else if(n.event_id){selectedEvent=n.event_id;view='schedule';closeModal();render()}else{modal(`<div class="sheethead"><h2>${esc(n.title)}</h2><button class="close" data-close>×</button></div><div class="card"><p>${esc(n.body||'')}</p></div>`)}}
function announcementModal(){modal(`<div class="sheethead"><h2>Enviar aviso</h2><button class="close" data-close>×</button></div><form class="form" id="announce"><div class="field"><label>Alcance</label><select name="scope"><option value="general">General · todos</option><option value="team">Equipo</option></select></div><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Mensaje</label><textarea name="body" required></textarea></div><button class="btn primary">Enviar</button></form>`);$('#announce').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let rows=S.people.filter(p=>p.auth_user_id&&p.active).map(p=>({person_id:p.id,scope:f.get('scope'),title:f.get('title'),body:f.get('body')}));let {error}=await sb.from('tnt_notifications').insert(rows);if(error)return showError(error);closeModal();toast('Aviso enviado');await loadAll()}}

function generateLocalReminders(){if(!me)return;let key='tnt-reminders-'+today(),done=new Set(JSON.parse(localStorage.getItem(key)||'[]'));let mine=S.assignees.filter(a=>a.person_id===myId());let messages=[];mine.forEach(a=>{let t=task(a.task_id);if(!t)return;if(a.assignment_status==='assigned'&&!done.has('read:'+t.id))messages.push({k:'read:'+t.id,title:'🔔 Tenés una asignación sin confirmar',body:t.title});if(t.due_at){let d=t.due_at.slice(0,10),tom=new Date();tom.setDate(tom.getDate()+1);if(d===tom.toISOString().slice(0,10)&&!done.has('due:'+t.id))messages.push({k:'due:'+t.id,title:'⏰ Tu tarea vence mañana',body:t.title})}});S.events.forEach(e=>{let tom=new Date();tom.setDate(tom.getDate()+1);if(e.start_date===tom.toISOString().slice(0,10)&&!done.has('event:'+e.id))messages.push({k:'event:'+e.id,title:'📅 El evento comienza mañana',body:e.name})});if(Notification.permission==='granted')messages.forEach(m=>new Notification(m.title,{body:m.body}));messages.forEach(m=>done.add(m.k));localStorage.setItem(key,JSON.stringify([...done]))}

function eventEditor(ev=null,kind='event'){
  let organizers=ev?eventOrganizers(ev.id).map(p=>p.id):[];
  modal(`<div class="sheethead"><h2>${ev?'Editar':'Nuevo'} ${kind==='saturday'?'sábado':'evento'}</h2><button class="close" data-close>×</button></div><form class="form" id="eventForm"><div class="field"><label>Nombre</label><input name="name" value="${esc(ev?.name|| (kind==='saturday'?'TNT · '+fmt(today()):''))}" required></div><div class="formRow"><div class="field"><label>Desde</label><input type="date" name="start" value="${esc(ev?.start_date||today())}" required></div><div class="field"><label>Hasta</label><input type="date" name="end" value="${esc(ev?.end_date||ev?.start_date||today())}" required></div></div><div class="field"><label>Lugar</label><input name="location" value="${esc(ev?.location||'')}"></div><div class="field"><label>Descripción</label><textarea name="desc">${esc(ev?.description||'')}</textarea></div>${!ev?`<div class="field"><label>Plantilla</label><select name="template"><option value="">Sin plantilla</option>${S.templates.filter(t=>kind==='saturday'?t.kind==='saturday':true).map(t=>`<option value="${t.id}" ${kind==='saturday'&&t.name==='Sábado normal'?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Organizadores del evento</label><div class="checkGrid">${S.people.filter(p=>p.active).map(p=>`<label class="check"><input type="checkbox" name="organizer" value="${p.id}" ${organizers.includes(p.id)?'checked':''}><span>${esc(p.nickname||p.full_name)}</span></label>`).join('')}</div></div><button class="btn primary">Guardar</button></form>`,true);
  $('#eventForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),payload={kind:ev?.kind||kind,name:String(f.get('name')).trim(),description:String(f.get('desc')||'').trim()||null,location:String(f.get('location')||'').trim()||null,start_date:f.get('start'),end_date:f.get('end'),created_by:ev?.created_by||myId()};try{let saved;if(ev){let r=await sb.from('tnt_events').update(payload).eq('id',ev.id).select().single();if(r.error)throw r.error;saved=r.data;await sb.from('tnt_event_members').delete().eq('event_id',ev.id).eq('event_role','organizer')}else{payload.template_id=f.get('template')||null;let r=await sb.from('tnt_events').insert(payload).select().single();if(r.error)throw r.error;saved=r.data}let orgs=f.getAll('organizer').map(String);if(orgs.length){let r=await sb.from('tnt_event_members').insert(orgs.map(person_id=>({event_id:saved.id,person_id,event_role:'organizer'})));if(r.error)throw r.error}if(!ev&&payload.template_id){let tis=S.templateItems.filter(i=>i.template_id===payload.template_id);if(tis.length){let r=await sb.from('tnt_tasks').insert(tis.map(i=>({event_id:saved.id,title:i.title,icon:i.icon,task_type:i.task_type,description:i.description,sort_order:i.sort_order,created_by:myId()})));if(r.error)throw r.error}}if(!ev){let r=await sb.from('tnt_schedule_days').insert({event_id:saved.id,label:kind==='saturday'?'Sábado':'Día 1',date:saved.start_date,sort_order:0});if(r.error)throw r.error}selectedEvent=saved.id;closeModal();toast('Evento guardado');await loadAll()}catch(err){showError(err)}}
}

function dayEditor(){let ev=event(selectedEvent),days=S.days.filter(d=>d.event_id===selectedEvent);modal(`<div class="sheethead"><h2>Agregar día</h2><button class="close" data-close>×</button></div><form class="form" id="dayForm"><div class="field"><label>Nombre</label><input name="label" value="Día ${days.length+1}" required placeholder="Día 1 / Viernes"></div><div class="field"><label>Fecha</label><input type="date" name="date" value="${esc(ev?.start_date||today())}"></div><button class="btn primary">Agregar</button></form>`);$('#dayForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),{data,error}=await sb.from('tnt_schedule_days').insert({event_id:selectedEvent,label:f.get('label'),date:f.get('date')||null,sort_order:days.length}).select().single();if(error)return showError(error);selectedDay=data.id;closeModal();await loadAll()}}

function itemEditor(existing=null){let day=S.days.find(d=>d.id===selectedDay),cur=existing?itemResponsibles(existing.id).map(p=>p.id):[];modal(`<div class="sheethead"><h2>${existing?'Editar':'Nueva'} actividad</h2><button class="close" data-close>×</button></div><form class="form" id="itemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(existing?.title||'')}" required placeholder="Primer juego"></div><div class="field"><label>Tipo</label><select name="type"><option value="game" ${existing?.item_type==='game'?'selected':''}>Juego</option><option value="activity" ${existing?.item_type==='activity'?'selected':''}>Actividad</option><option value="meeting" ${existing?.item_type==='meeting'?'selected':''}>Reunión</option><option value="meal" ${existing?.item_type==='meal'?'selected':''}>Comida</option><option value="other">Otro</option></select></div></div><div class="formRow"><div class="field"><label>Hora</label><input type="time" name="time" value="${esc(existing?.starts_at?.slice(0,5)||'')}"></div><div class="field"><label>Duración (min)</label><input type="number" min="0" name="duration" value="${existing?.duration_minutes||''}"></div></div><div class="field"><label>Lugar</label><input name="location" value="${esc(existing?.location||'')}"></div><div class="field"><label>Video explicativo</label><input name="video" value="${esc(existing?.video_url||'')}" placeholder="https://youtube.com/..."></div><div class="field"><label>Descripción / instrucciones</label><textarea name="desc">${esc(existing?.description||'')}</textarea></div><div class="field"><label>Materiales necesarios</label><textarea name="materials">${esc(existing?.materials||'')}</textarea></div><div class="field"><label>Responsables</label><div class="checkGrid">${S.people.filter(p=>p.active).map(p=>`<label class="check"><input type="checkbox" name="resp" value="${p.id}" ${cur.includes(p.id)?'checked':''}><span>${esc(p.nickname||p.full_name)}</span></label>`).join('')}</div></div><button class="btn primary">Guardar</button></form>`,true);$('#itemForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),payload={day_id:selectedDay,title:f.get('title'),item_type:f.get('type'),starts_at:f.get('time')||null,duration_minutes:Number(f.get('duration'))||null,location:String(f.get('location')||'')||null,video_url:String(f.get('video')||'')||null,description:String(f.get('desc')||'')||null,materials:String(f.get('materials')||'')||null};try{let saved;if(existing){let r=await sb.from('tnt_schedule_items').update(payload).eq('id',existing.id).select().single();if(r.error)throw r.error;saved=r.data;await sb.from('tnt_schedule_responsibles').delete().eq('item_id',existing.id)}else{payload.sort_order=dayItems(selectedDay).length;let r=await sb.from('tnt_schedule_items').insert(payload).select().single();if(r.error)throw r.error;saved=r.data}let ids=f.getAll('resp').map(String);if(ids.length){let r=await sb.from('tnt_schedule_responsibles').insert(ids.map(person_id=>({item_id:saved.id,person_id})));if(r.error)throw r.error}closeModal();await loadAll()}catch(err){showError(err)}}}

function itemDetail(id){let i=S.items.find(x=>x.id===id),d=S.days.find(x=>x.id===i?.day_id),rs=itemResponsibles(id),vid=youtubeId(i?.video_url||'');if(!i)return;modal(`<div class="sheethead"><div><div class="eyebrow">${esc(d?.label||'')} · ${time(i.starts_at)}</div><h2>${esc(i.title)}</h2></div><button class="close" data-close>×</button></div><div class="chips"><span class="chip">${esc(i.item_type)}</span>${i.duration_minutes?`<span class="chip">${i.duration_minutes} min</span>`:''}${i.location?`<span class="chip">📍 ${esc(i.location)}</span>`:''}</div>${vid?`<div class="video"><iframe src="https://www.youtube.com/embed/${encodeURIComponent(vid)}" allowfullscreen></iframe></div>`:i.video_url?`<a class="card" style="display:block;margin-top:12px;color:inherit" target="_blank" href="${esc(i.video_url)}">▶ Abrir video explicativo</a>`:''}<div class="section"><h2>Responsables</h2></div><div class="chips">${rs.map(p=>`<button class="btn small" data-r-person="${p.id}">${esc(p.nickname||p.full_name)}</button>`).join('')||'<span class="muted">Sin responsables</span>'}</div><div class="section"><h2>Instrucciones</h2></div><div class="card"><p>${esc(i.description||'Sin instrucciones')}</p></div><div class="section"><h2>Materiales</h2></div><div class="card"><p>${esc(i.materials||'Sin materiales cargados')}</p></div>${canManage(d?.event_id)?'<div class="toolbar" style="margin-top:16px"><button class="btn primary" id="editItem">Editar</button></div>':''}`,true);$('#editItem')?.addEventListener('click',()=>itemEditor(i));$$('[data-r-person]').forEach(b=>b.onclick=()=>responsibilitiesModal(b.dataset.rPerson))}

function responsibilitiesModal(pid){let p=person(pid);if(!p)return;let sched=S.responsibles.filter(r=>r.person_id===pid).map(r=>{let i=S.items.find(x=>x.id===r.item_id),d=S.days.find(x=>x.id===i?.day_id),e=event(d?.event_id);return i?{i,d,e}:null}).filter(Boolean);let assigns=S.assignees.filter(a=>a.person_id===pid).map(a=>({a,t:task(a.task_id)})).filter(x=>x.t);modal(`<div class="sheethead"><h2>${esc(p.nickname||p.full_name)} · responsabilidades</h2><button class="close" data-close>×</button></div><div class="section"><h2>Cronograma</h2></div><div class="list">${sched.map(x=>`<div class="rowCard"><div class="ico">🗓</div><div><h4>${esc(x.i.title)}</h4><p>${esc(x.e?.name||'')} · ${esc(x.d?.label||'')} · ${time(x.i.starts_at)}</p></div></div>`).join('')||'<div class="empty">Sin responsabilidades de cronograma.</div>'}</div><div class="section"><h2>Tareas</h2></div><div class="list">${assigns.map(x=>`<button class="rowCard" data-r-task="${x.t.id}"><div class="ico">${esc(x.t.icon||'✓')}</div><div><h4>${esc(x.t.title)}</h4><p>${esc(event(x.t.event_id)?.name||'')} · ${assignmentLabel(x.a.assignment_status)}</p></div><span class="status ${x.t.status}">${statusLabel(x.t.status)}</span></button>`).join('')||'<div class="empty">Sin tareas asignadas.</div>'}</div>`,true);$$('[data-r-task]').forEach(b=>b.onclick=()=>taskModalView(b.dataset.rTask))}

function taskModalView(id){let t=task(id),ev=event(t?.event_id),a=S.assignees.find(x=>x.task_id===id&&x.person_id===myId()),ass=taskAssignees(id),ls=S.links.filter(x=>x.task_id===id),cks=S.checks.filter(x=>x.task_id===id).sort((a,b)=>a.sort_order-b.sort_order),cs=S.comments.filter(x=>x.task_id===id).sort((a,b)=>a.created_at.localeCompare(b.created_at)),children=S.tasks.filter(x=>x.parent_task_id===id);if(!t)return;let editable=canManage(t.event_id),collab=editable||!!a;modal(`<div class="sheethead"><div><div class="eyebrow">${esc(ev?.name||'')}</div><h2>${esc(t.icon||'✓')} ${esc(t.title)}</h2></div><button class="close" data-close>×</button></div><div class="chips"><span class="status ${t.status}">${statusLabel(t.status)}</span><span class="chip">${t.priority==='high'?'Prioridad alta':t.priority==='low'?'Prioridad baja':'Prioridad media'}</span>${t.due_at?`<span class="chip">Vence ${fmt(t.due_at.slice(0,10))}</span>`:''}</div>${a?`<div class="section"><h2>Tu asignación</h2></div><div class="card"><p>Estado: <b>${assignmentLabel(a.assignment_status)}</b></p><div class="toolbar" style="margin-top:10px">${a.assignment_status==='assigned'?'<button class="btn" data-response="read">Ya lo leí</button>':''}${a.assignment_status!=='accepted'&&a.assignment_status!=='declined'?'<button class="btn green" data-response="accepted">Acepto</button><button class="btn danger" data-response="declined">No puedo hacerlo</button>':''}</div></div>`:''}<div class="section"><h2>Responsables</h2>${editable?'<button class="btn small" id="editTask">Editar</button>':''}</div><div class="chips">${ass.map(x=>`<span class="chip">${esc(x.person?.nickname||x.person?.full_name||'')} · ${assignmentLabel(x.assignment_status)}</span>`).join('')||'<span class="muted">Sin asignados</span>'}</div><div class="section"><h2>Planificación</h2></div><div class="card"><p>${esc(t.description||'Sin descripción')}</p>${t.materials?`<p><b>Materiales:</b> ${esc(t.materials)}</p>`:''}${t.budget_estimated!=null?`<p><b>Presupuesto estimado:</b> $${Number(t.budget_estimated).toLocaleString('es-AR')}</p>`:''}${editable&&t.private_notes?`<p><b>Notas privadas organizadores:</b> ${esc(t.private_notes)}</p>`:''}</div><div class="section"><h2>Estado de ejecución</h2></div>${collab?`<div class="toolbar">${['preparing','progress','review','ready','completed'].map(s=>`<button class="btn small ${t.status===s?'green':''}" data-task-status="${s}">${statusLabel(s)}</button>`).join('')}</div>`:''}<div class="section"><h2>Referencias</h2>${collab?'<button class="btn small" id="addLink">+ Link</button>':''}</div><div class="grid g2">${ls.map(l=>linkCard(l)).join('')||'<div class="empty">Sin links.</div>'}</div><div class="section"><h2>Checklist / subtareas</h2>${editable?'<button class="btn small" id="addSubtask">+ Subtarea</button>':''}</div><div class="list">${cks.map(c=>`<label class="check"><input type="checkbox" data-check-id="${c.id}" ${c.done?'checked':''} ${collab?'':'disabled'}><span style="${c.done?'text-decoration:line-through;color:#8f98a9':''}">${esc(c.text)}</span></label>`).join('')}${children.map(ch=>`<button class="rowCard" data-child-task="${ch.id}"><div class="ico">↳</div><div><h4>${esc(ch.title)}</h4><p>Subtarea</p></div><span class="status ${ch.status}">${statusLabel(ch.status)}</span></button>`).join('')}</div><div class="section"><h2>Archivos</h2>${collab?'<button class="btn small" id="uploadFile">+ Archivo</button>':''}</div><div class="list">${S.files.filter(f=>f.task_id===id).map(f=>`<button class="rowCard" data-file="${f.id}"><div class="ico">📎</div><div><h4>${esc(f.file_name)}</h4><p>${esc(f.mime_type||'archivo')}</p></div><span class="arr">›</span></button>`).join('')||'<div class="empty">Sin archivos.</div>'}</div><div class="section"><h2>Comentarios</h2></div><div class="list">${cs.map(c=>{let p=person(c.person_id);return `<div class="card"><h3>${esc(p?.nickname||p?.full_name||'Usuario')}</h3><p>${esc(c.body)}</p></div>`}).join('')||'<div class="empty">Sin comentarios.</div>'}</div>${collab?`<form class="form" id="commentForm"><div class="field"><textarea name="body" placeholder="Escribí un comentario…" required></textarea></div><button class="btn">Comentar</button></form>`:''}`,true);
  $('#editTask')?.addEventListener('click',()=>taskEditor(t));
  $$('[data-response]').forEach(b=>b.onclick=async()=>{let note=null;if(b.dataset.response==='declined')note=prompt('¿Querés contar por qué no podés?')||null;let {error}=await sb.rpc('tnt_set_assignment_response',{p_task:id,p_status:b.dataset.response,p_note:note});if(error)return showError(error);toast(b.dataset.response==='declined'?'Organizadores avisados':'Asignación actualizada');closeModal();await loadAll()});
  $$('[data-task-status]').forEach(b=>b.onclick=async()=>{let {error}=await sb.rpc('tnt_set_task_status',{p_task:id,p_status:b.dataset.taskStatus});if(error)return showError(error);closeModal();await loadAll()});
  $$('[data-check-id]').forEach(b=>b.onchange=async()=>{let {error}=await sb.from('tnt_task_checklist').update({done:b.checked}).eq('id',b.dataset.checkId);if(error)showError(error)});
  $('#addLink')?.addEventListener('click',()=>addLinkModal(id));
  $('#addSubtask')?.addEventListener('click',()=>taskEditor(null,t.event_id,t.id));
  $('#uploadFile')?.addEventListener('click',()=>fileUploadModal(id));
  $$('[data-file]').forEach(b=>b.onclick=()=>openFile(b.dataset.file));
  $$('[data-child-task]').forEach(b=>b.onclick=()=>taskModalView(b.dataset.childTask));
  $('#commentForm')?.addEventListener('submit',async e=>{e.preventDefault();let body=new FormData(e.target).get('body');let {error}=await sb.from('tnt_task_comments').insert({task_id:id,person_id:myId(),body});if(error)return showError(error);await loadAll();taskModalView(id)});
}
function linkCard(l){let vid=l.link_type==='youtube'?youtubeId(l.url):'';return `<a class="card" href="${esc(l.url)}" target="_blank" rel="noopener" style="color:inherit;text-decoration:none"><div class="ico">${iconForLink(l.url)}</div><h3 style="margin-top:10px">${esc(l.label||l.link_type)}</h3><p>${esc(l.url)}</p>${vid?`<img src="https://i.ytimg.com/vi/${encodeURIComponent(vid)}/hqdefault.jpg" style="width:100%;margin-top:10px;border-radius:12px">`:''}</a>`}
function addLinkModal(taskId){modal(`<div class="sheethead"><h2>Agregar referencia</h2><button class="close" data-close>×</button></div><form class="form" id="linkForm"><div class="field"><label>URL</label><input name="url" required placeholder="YouTube, Pinterest, Drive, Canva…"></div><div class="field"><label>Título</label><input name="label"></div><button class="btn primary">Agregar</button></form>`);$('#linkForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),u=String(f.get('url')).trim();let {error}=await sb.from('tnt_task_links').insert({task_id:taskId,url:u,label:String(f.get('label')||'').trim()||null,link_type:linkType(u)});if(error)return showError(error);await loadAll();taskModalView(taskId)}}
function fileUploadModal(taskId){modal(`<div class="sheethead"><h2>Subir archivo</h2><button class="close" data-close>×</button></div><form class="form" id="fileForm"><div class="field"><label>Archivo</label><input type="file" name="file" required></div><button class="btn primary">Subir</button></form>`);$('#fileForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),file=f.get('file'),path=`tasks/${taskId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;let up=await sb.storage.from('tnt-files').upload(path,file);if(up.error)return showError(up.error);let {error}=await sb.from('tnt_task_files').insert({task_id:taskId,storage_path:path,file_name:file.name,mime_type:file.type,size_bytes:file.size,uploaded_by:myId()});if(error)return showError(error);await loadAll();taskModalView(taskId)}}
async function openFile(id){let f=S.files.find(x=>x.id===id);if(!f)return;let {data,error}=await sb.storage.from('tnt-files').createSignedUrl(f.storage_path,120);if(error)return showError(error);window.open(data.signedUrl,'_blank')}

function taskEditor(existing=null,eventId=selectedEvent,parentId=null){let ass=existing?taskAssignees(existing.id).map(x=>x.person_id):[];let links=existing?S.links.filter(l=>l.task_id===existing.id).map(l=>l.url).join('\n'):'';let checks=existing?S.checks.filter(c=>c.task_id===existing.id).map(c=>c.text).join('\n'):'';let avDate=existing?.due_at?.slice(0,10)||event(eventId)?.start_date;let warnings=assignmentWarnings(ass,avDate,eventId);modal(`<div class="sheethead"><h2>${existing?'Editar':'Nueva'} tarea</h2><button class="close" data-close>×</button></div><form class="form" id="taskForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(existing?.title||'')}" required></div><div class="field"><label>Ícono</label><input name="icon" value="${esc(existing?.icon||'✓')}"></div></div><div class="formRow"><div class="field"><label>Tipo</label><select name="type"><option value="simple" ${existing?.task_type==='simple'?'selected':''}>Simple</option><option value="complex" ${existing?.task_type==='complex'?'selected':''}>Compleja</option></select></div><div class="field"><label>Prioridad</label><select name="priority"><option value="low">Baja</option><option value="medium" ${existing?.priority!=='high'?'selected':''}>Media</option><option value="high" ${existing?.priority==='high'?'selected':''}>Alta</option></select></div></div><div class="formRow"><div class="field"><label>Fecha límite</label><input type="date" name="due" value="${esc(existing?.due_at?.slice(0,10)||'')}"></div><div class="field"><label>Presupuesto estimado</label><input type="number" step="0.01" name="budget" value="${existing?.budget_estimated??''}"></div></div><div class="field"><label>Responsables</label><div class="checkGrid">${S.people.filter(p=>p.active).map(p=>`<label class="check"><input type="checkbox" name="assignee" value="${p.id}" ${ass.includes(p.id)?'checked':''}><span>${esc(p.nickname||p.full_name)}</span></label>`).join('')}</div></div>${warnings?`<div class="warn">${warnings}</div>`:''}<div class="field"><label>Descripción / planificación</label><textarea name="desc">${esc(existing?.description||'')}</textarea></div><div class="field"><label>Materiales necesarios</label><textarea name="materials">${esc(existing?.materials||'')}</textarea></div><div class="field"><label>Notas privadas para organizadores</label><textarea name="private">${esc(existing?.private_notes||'')}</textarea></div><div class="field"><label>Links / referencias · uno por línea</label><textarea name="links">${esc(links)}</textarea></div><div class="field"><label>Checklist · un punto por línea</label><textarea name="checks">${esc(checks)}</textarea></div><button class="btn primary">Guardar tarea</button></form>`,true);$('#taskForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),due=f.get('due')?new Date(String(f.get('due'))+'T18:00:00').toISOString():null,payload={event_id:eventId,parent_task_id:existing?.parent_task_id||parentId,title:f.get('title'),icon:f.get('icon')||'✓',task_type:f.get('type'),priority:f.get('priority'),due_at:due,budget_estimated:f.get('budget')?Number(f.get('budget')):null,description:String(f.get('desc')||'')||null,materials:String(f.get('materials')||'')||null,private_notes:String(f.get('private')||'')||null,created_by:existing?.created_by||myId()};try{let saved;if(existing){let r=await sb.from('tnt_tasks').update(payload).eq('id',existing.id).select().single();if(r.error)throw r.error;saved=r.data}else{let r=await sb.from('tnt_tasks').insert(payload).select().single();if(r.error)throw r.error;saved=r.data}let ids=f.getAll('assignee').map(String),old=new Map(S.assignees.filter(a=>a.task_id===saved.id).map(a=>[a.person_id,a]));await sb.from('tnt_task_assignees').delete().eq('task_id',saved.id);if(ids.length){let r=await sb.from('tnt_task_assignees').insert(ids.map(person_id=>({task_id:saved.id,person_id,assignment_status:old.get(person_id)?.assignment_status||'assigned',read_at:old.get(person_id)?.read_at||null,responded_at:old.get(person_id)?.responded_at||null})));if(r.error)throw r.error}await sb.from('tnt_task_links').delete().eq('task_id',saved.id);let urls=String(f.get('links')||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);if(urls.length)await sb.from('tnt_task_links').insert(urls.map((url,i)=>({task_id:saved.id,url,link_type:linkType(url),sort_order:i})));await sb.from('tnt_task_checklist').delete().eq('task_id',saved.id);let cks=String(f.get('checks')||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);if(cks.length)await sb.from('tnt_task_checklist').insert(cks.map((text,i)=>({task_id:saved.id,text,sort_order:i})));closeModal();await loadAll();taskModalView(saved.id)}catch(err){showError(err)}}}
function assignmentWarnings(ids,date,eventId){let arr=[];ids.forEach(id=>{let p=person(id),av=S.availability.find(a=>a.person_id===id&&a.date===date);if(av?.status==='unavailable')arr.push(`⚠️ ${p?.nickname||p?.full_name} indicó que no está disponible.`);if(av?.status==='maybe')arr.push(`🟡 ${p?.nickname||p?.full_name} probablemente no pueda.`);let same=S.assignees.filter(a=>a.person_id===id).map(a=>task(a.task_id)).filter(t=>t&&t.event_id===eventId).length;if(same>=2)arr.push(`⚠️ ${p?.nickname||p?.full_name} ya tiene ${same} asignaciones en este evento.`);let month=(date||today()).slice(0,7),count=S.assignees.filter(a=>a.person_id===id).map(a=>task(a.task_id)).filter(t=>t&&(t.due_at?.startsWith(month)||event(t.event_id)?.start_date?.startsWith(month))).length;if(count>=4)arr.push(`⚠️ ${p?.nickname||p?.full_name} ya tiene ${count} asignaciones este mes.`)});return arr.join('<br>')}

